function cleanMetaString(text: string, commerceEnabled: boolean, fallback: string, locale: string): string {
  const vacant = fallbackLead(locale);
  const base = commerceEnabled ? text : (stripCommerceSentences(text) || text);
  if (!UNRESOLVED_SLOT.test(base)) return base.trim() || fallback.trim() || vacant;
  return withoutPlaceholders(base) || withoutPlaceholders(fallback) || vacant;
}

export function publicCardPageMeta(
  meta: CardPageDocument['meta'],
  commerceEnabled: boolean,
  locale = 'ru',
): CardPageDocument['meta'] {
  const ogSource = meta.ogDescription
    ? cleanMetaString(meta.ogDescription, commerceEnabled, '', locale)
    : '';
  const { ogDescription: _ogDescription, ...metaRest } = meta;
  return {
    ...metaRest,
    title: cleanMetaString(meta.title, commerceEnabled, meta.title, locale),
    description: cleanMetaString(meta.description, commerceEnabled, fallbackLead(locale), locale),
    ...(meta.h1 ? { h1: cleanMetaString(meta.h1, commerceEnabled, meta.h1, locale) } : {}),
    ...(ogSource ? { ogDescription: ogSource } : {}),
  };
}

